// Function Prototype (Declaration)
int calculate(int x, int y);

// Function Definition
int calculate(int x, int y) {
    return (x * 2) + y;
}

// Function Call (Pass by Value)
int arg1 = 10;
int arg2 = 5;
int sum = calculate(arg1, arg2);

// Void Function Call (No return value)
void log_event();
log_event();

// Direct Literal Call
int literal_result = calculate(3, 1);
